def compute(vars):
    receivables = vars["v1"]
    revenue = vars["v2"]
    if revenue == 0:
        return None
    value = receivables / revenue * 100
    return {
        "value": value,
        "trace": {
            "accounts_receivable": receivables,
            "revenue": revenue,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
